"Anyone remember why the sky is a portal?":"Își amintește cineva de ce cerul e un portal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Se zice că dacă sari în puț, ieși la inamic. Nu testez.",
"The Swarm painted their visors red again. Show-offs.":"Roiul și-a vopsit iar vizierele în roșu. Fanfaroni.",
"Ore, ore… when do we get some oil?":"Minereu, minereu… dar uleiul când îl primim?",
"I dreamt I was a toaster. It was peaceful.":"Am visat că eram un prăjitor de pâine. A fost liniște.",
"Quiet. Too quiet.":"Liniște. Prea multă liniște.",
"See that? Our base is above the Swarm base again. Portals, man.":"Ați văzut? Deasupra bazei Roiului e iar baza noastră. Portaluri, mă.",
