"robot war · the sky is a portal":"război de roboți · cerul e un portal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Bun venit pe meteorit! Ești un robot de luptă al Consorțiului. Privește în jur cu mouse-ul și mergi cu WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: apasă Shift pentru un salt, ține Shift pentru zbor. Energia se reface pe sol.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Tragi — clic stânga. Țintești — clic dreapta: mai precis, cu zoom. Trage câteva focuri.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Reîncărcare — R. Gloanțele lovesc cel mai tare la distanță medie, 20–50 de metri.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Rachetă — Q. Împotriva tancurilor și clădirilor. Lansează o rachetă.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Sus e ordinul strategului. Aleargă pe săgețile verzi: pe traseu ai sprint. Capturează punctul — stai lângă baliză.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Echipa ta îți acoperă spatele: portretele și sănătatea lor sunt în stânga. Dacă rămân în urmă, îți vor cere să aștepți.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — schimbare rapidă de unitate fără să ieși din luptă: sari în echipa sau tancul cel mai apropiat de luptă. Încearcă.",
"Next to a tank or turret press E to take control. Or just carry on.":"Lângă un tanc sau o turelă apasă E ca să preiei controlul. Sau pur și simplu mergi mai departe.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Acum strategia. Atinge „◩ Strategie\" în dreapta sus — vedere de sus a câmpului de luptă.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Acum strategia. Apasă {0} (sau „◩ Strategie\" în stânga sus) — vedere de sus a câmpului de luptă.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"În modul Strategist te ajută Curatorul: caseta de sus spune ce ai de făcut, un cadru arată butonul, un inel marchează locul pe hartă. Îndeplinește trei sfaturi de-ale lui.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Selectează o echipă și atinge butonul verde „▶ Stăpânește\" — înapoi în luptă ca acel soldat. Cât tragi tu, strategul IA conduce armata.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Selectează o echipă și apasă {0} sau butonul verde „▶ Stăpânește\" — înapoi în luptă ca acel soldat (fără selecție — la al tău). Cât tragi tu, strategul IA conduce armata.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Antrenament încheiat! Roiul începe ofensiva. Succes, soldat!",
