"Squads jet up through the dome portal and land at the enemy.":"Echipele zboară cu jetpack-uri, trec prin portalul domului și aterizează la inamic.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"Controlezi tu soldatul, tancul sau turela selectată. Aceeași tastă în luptă te readuce la strategie.",
