"New in v6.2":"Noutăți în v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Aspect nou al minereului: filoanele sunt cristale smarald fațetate și strălucitoare pe bazalt negru, cu scântei și ceață verde; Extractorul e un postament hexagonal cu dom în fagure și un turn zăbrelit cu far verde în vârf (dungă și fanion în culoarea echipei)",
"New in v6.1":"Noutăți în v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Clasă preferată ca în Battlefield (U, cifre după moarte): reapari direct în ea când e disponibilă",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Vehicule la persoana întâi (V — din afară/din cabină); asistență ușoară la țintire — în Setări",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Ieșire ușoară din nucleu: Spațiu — spre puț, B — capsulă la suprafață; efectele abilităților se resetează la moarte",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Progresie nesfârșită: generali și Mareșal ★, niveluri de carieră, măiestrie la arme și accesorii, medalii, contracte zilnice — ecranul Carieră",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strategie: zoom fluid cu rotița, pictograme și etichete deasupra unităților (Alt — toate), panoul „Trupe / Clădiri\" în stânga",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"clic dreapta — mișcare de atac, dublu clic dreapta — marș cu foc din mers; ordine rare — în „Mai multe ordine ▾\"; fără butoane duplicate",
"New in v6":"Noutăți în v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Arme ca în shootere: gloanțe instantanee, pușcă de 720 lovituri/min, mitralieră, recul, țintire cu clic dreapta, încărcătoare și reîncărcare cu R, marcaje de lovitură",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Gravitație mai grea, jetpack mai receptiv, avânt cu Z sau dublu jetpack în aer; arma nu mai zboară după tine la schimbarea unității",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Ingineri constructori: selectează un inginer, alege clădirea, plasează planul; extractoare pe filoanele de minereu; clic pe „MINEREU\" — de unde vine venitul și cum îl crești",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Butoanele gri explică de ce nu merg și oferă o soluție; butoane mai mari, banda „În lucru\", „▶ Preia controlul\", Tab — o singură tastă de mod",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Cameră strategică fără sacadări sau răsturnări, zoom spre cursor, minihartă care se poate trage",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Tehnică nouă: raider „Șacal\", MLRS „Grad\" (rachete autoghidate), mortier „Ciocan\"; Roiul primește „Viespe\", „Stup\", „Trebușet\"",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strategul nu schimbă ordinele și nu mai spamează vocea; luptele vin spre tine; B — redesfășurare, Shift+B — în focul luptei; busolă, H — ce țintă",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Acțiune liberă (K) și acționez singur (J), F2 — presetări; Esc — pauză și înapoi; salvări: sloturi, export și import de fișier",
"New in v5.3":"Noutăți în v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Zbor: gravitație mai puternică departe de meteorit, C în aer — frână, tracțiunea virează mai ascuțit; nu mai rămâi „agățat\" în portal",
"New in v5":"Noutăți în v5",
