"Panel":"Panou",
"Battle":"În luptă",
"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"Mitraliorul greu al Consorțiului este acum un model 3D real, cu schelet: stă, merge, aleargă cu arma, trage din mișcare și cade spectaculos când e distrus",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Modelul stă pe normala suprafeței meteoritului, își rotește trunchiul după țintă și ține mitraliera în mâini; de departe animația se actualizează mai rar ca să nu scadă FPS-ul",
"New in v6.5":"Noutăți în v6.5",
"Barracks":"Cazarmă",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"Infanterie: echipe de asalt, mitralieri grei, lunetiști, iscoade, capsule de desant; upgrade-uri de armură și arme.",
"Ore depot":"Depozit de minereu",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"Aici inginerii predau cristalele. Pune-l lângă un câmp de cristale — drumuri mai scurte, mai mult minereu.",
"Tanks and vehicles. Requires Barracks.":"Tancuri și vehicule. Necesită Cazarmă.",
"Autonomous combat drones. Requires Barracks.":"Drone de luptă autonome. Necesită Cazarmă.",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"Jetpackuri II și Trupe aeriene (elită cu jetpack). Necesită o fabrică de mecha, se deblochează la 6:00.",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"Bază avansată la un punct deținut: ingineri, predare cristale, completare efective.",
