"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"Jetpackurile și aviația se deblochează mai târziu — ai timp să pui apărare antiaeriană și turete. Între timp construiește Cazarmă și o fabrică de mecha.",
