"No crystal field near a drop-off":"Niciun câmp de cristale lângă un punct de predare",
"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"Extrage cristale: inginerul ia o încărcătură de la un câmp verde și o duce la cartierul general/depozit. Sau clic dreapta pe cristale.",
