"Voice of hints & curator":"Vocea indiciilor și a curatorului",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: trei moduri de joystick. Doar stânga — „auto\" (magnet puternic, gloanțe mai slabe). Doar dreapta — ținta pornește singură, magnet mai puternic, precizie mai bună. Amândouă — fără țintă, magnet și precizie mai slabe. Butonul 👁 din dreapta ascunde/readuce interfața.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strategie simplificată — doar inginer și clădiri. Cărți în stânga (inginer, cartier general, cazarmă…): atingere — camera zboară acolo, bara de jos arată ce construiești/produci. „La luptă\" — sus în stânga. Armata luptă singură. Strategia completă — Setări → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Preluarea controlului — două comutatoare: „Echipe\" și „Vehicule\" (pe telefoane vehiculele sunt oprite implicit — le conduce IA). Cu vehiculele oprite, E (pe telefon — butonul din dreapta) lângă un vehicul prietenos — urci la tun: vehiculul merge singur, tu tragi. Vechea ordine proprie a claselor e la „Avansate\". O unitate răspunde la stație când îi preiei controlul.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Indicii inteligente: cele de bază se sting singure după a 2-a pornire, dar jocul îți indică o funcție pe care nu o folosești niciodată. Comutatoare: de bază / avansate / rare, iar separat — vocea indiciilor și a curatorului.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Reflexul se încarcă din eliminări (seriile încarcă mai mult). Camarazii au rămas în urmă sau au murit — strategul îți trimite alții noi (mai scump decât întăririle obișnuite). Grafica și sunetul v7.2gfx sunt integrate: explozii în volute, fum, dărâmături, acustica puțurilor și a craterelor. Data versiunii e reală acum.",
