"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"Cerul e un portal: dacă zbori în sus, ieși pe partea opusă a meteoritului.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"Urmează ordinele strategului — experiența pentru ele se dublează și se triplează.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — treci instant la echipa sau vehiculul cel mai aproape de luptă.",
"Bullets hit hardest at medium range, 20–50 meters.":"Gloanțele lovesc cel mai tare la distanță medie, 20–50 de metri.",
"To win, destroy the Swarm HQ and all its key buildings.":"Ca să câștigi, distruge Cartierul general al Roiului și toate clădirile lui cheie.",
