"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Cariera și salvările rămân neschimbate. În luptă, același meniu e butonul „🛠 Meniu\" din dreapta sus{0}.",
"New developer match":"Meci nou de dezvoltator",
"all unlocked, endless ore, instant build, arsenal":"totul deblocat, minereu nesfârșit, construcție instantanee, arsenal",
"Trainings — all 4":"Antrenamente — toate 4",
"PC and phone (strategy and shooter)":"PC și telefon (strategie și trăgător)",
"Cinema: split screen":"Cinema: ecran divizat",
"strategist bot left, shooter bot right":"bot strateg în stânga, bot trăgător în dreapta",
"Cinema: everything built":"Cinema: totul construit",
"both bases built and upgraded — for footage":"ambele baze construite și îmbunătățite — pentru filmări",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Mod cinema — ecran divizat: în stânga botul strateg (vedere de sus asupra bazei și armatei), în dreapta botul trăgător la persoana întâi. Butoane jos (și tastele S, P): „Ecran divizat\" și „★ Totul construit\" — ambele baze construite și îmbunătățite pentru filmări.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Nucleul și tunelurile prin meteorit nu mai există — meteoritul e compact, lupta se dă doar la suprafață.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 ascunde interfața, dar păstrează jetpackul, ⇆, joystick-urile și marcajul obiectivului. „◎ Țintă” (doar degetul drept) — un magnet vizibil mai puternic și mai larg; puterea magnetului pentru cele trei moduri — Setări → Comenzi → „Avansate”. La tunul unui vehicul, butonul se numește „Coboară”.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Antrenament: pe telefon — doar cele pentru telefon, pe PC — doar cele pentru PC. Toate 4 sunt în meniul „🛠 Dezvoltator”. Modul dezvoltator și Arsenalul sunt acum un singur meniu (în luptă — „🛠 Meniu” sus în dreapta, pe PC — F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Stilurile grafice „Dendy (8-bit)” și „16-bit”: Setări → Grafică → „Stil grafic” (detalii — butonul ⚙). Dacă în primele ~10 s ale meciului FPS-ul scade sub 24, Dendy se pornește singur (sub 20 — pixel și mai mare, 120 de linii); notificarea „revino la normal” readuce grafica normală definitiv. Alegerea ta din meniu are mereu prioritate.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"Modele 3D de mediu (ruine, epave, fortificații) — doar cele bine cotate, încărcate la cerere. Dezactivare: Setări → Grafică → „Modele 3D noi de mediu”.",
