"Prone / stand up (crawl)":"Culcă-te / ridică-te (târâș)",
"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Luptătorii pot construi: E (pe telefon „Enter”) la un șantier prietenos — luptătorul tău construiește, coechipierii din apropiere ajută. Dacă inginerii sunt ocupați, strategul îți cere ajutorul — marcajul „ȘANTIER”.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Marcajele strategului: strategul pune ⌖ pe un grup inamic de lângă tine — artileria lovește 8 s mai târziu, iar MLRS „Grad” aliate din apropiere trag o salvă. Lovitura ta de artilerie din modul strateg primește și ea sprijin de la „Grad”.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Ascunzători cu arme în containere de marfă și sateliți prăbușiți (📦 vizibile de la 70 m): E — o mitralieră grea pentru 90 s, muniție incendiară sau rachete, plus grenade pline. Târâș: Ctrl — culcă-te / ridică-te (mai jos, mai silențios, mai precis, dar lent).",
"Anonymous statistics":"Statistici anonime",
"no names or emails: version, device, play time — to make the game better":"fără nume sau e-mail: versiune, dispozitiv, timp de joc — ca să facem jocul mai bun",
"Anonymous statistics (no names or emails)":"Statistici anonime (fără nume sau e-mail)",
"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"Cinema în ecran împărțit, fără nucleu și tunele, luptătorii construiesc, marcajele strategului, ascunzători, târâș, meniul dezvoltatorului",
"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"Trei moduri de joystick pe telefon, strategie simplă, locul de la tunul vehiculului, relief cu canioane, clase de echipe, explozibili",
"Lite mode, two-stick phone controls":"Mod ușor, comenzi pe telefon cu două joystick-uri",
"Milestone: outposts and HQ upgrades, cinematic misses, knockdowns":"Reper: avanposturi și îmbunătățiri ale HQ, ratări cinematice, doborâri",
