"Link copied":"Link copiat",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Joacă acum” — primul buton din meniu: un scurt zbor sub cerul-portal și direct în luptă (sari peste cu orice tastă sau o atingere).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Loviturile se simt: sunet metalic și scântei, un marcaj de eliminare la țintă (lovitură în cap — galben), serie ×N, tremur lin la explozii, slow-mo la eliminările-cheie. Tremurul, slow-mo și indiciul pot fi dezactivate în Setări.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Rezultatul meciului: timp, distrugeri, cea mai bună serie, ★ MVP și cea mai bună echipă, cardul meciului — „⇪ Distribuie”, PNG sau link către joc.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Un indiciu „ce faci acum” în stânga, sub resurse: ordinul strategului, un punct de capturat, un atac al Roiului. ✕ sau F7 — restrânge.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Lupta se salvează singură dacă închizi sau ascunzi fila — „⟲ Continuă” în meniu.",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"v7.5 rămâne în meniul „🕘 Versiunea jocului”, în caz că o preferi. Acum se trimit statistici anonime (fără nume sau e-mail); dezactivare — în Setări.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Joacă acum”, reacția la lovituri, rezultatul meciului cu card de distribuit, indiciul „ce faci”, salvare automată",
"and older: v7.5, v7.4, milestones v1–v7.0":"și mai vechi: v7.5, v7.4, repere v1–v7.0",
"New in v7.6":"Noutăți în v7.6",
"NEW IN v7.6":"NOUTĂȚI ÎN v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Alegerea facțiunii înainte de meci: „Consorțiul” (infanterie grea în armură energetică, blindaj și artilerie) sau „Roiul” (viteză, haite de drone, lovituri grele cu distorsiune). IA o joacă pe cealaltă. Alegerea este reținută.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Fiecare facțiune are tehnica și unicatele ei: Consorțiul — tancul „Rinocer” și „Plăci de ceramit”, Roiul — „Haită de drone” și „Jetpackuri de fază”. Echilibrul a fost verificat cu meciuri între boți.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Cratere de explozie: artileria, rachetele și tunurile tancurilor sapă gropi în meteorit — poți merge și conduce prin ele și te poți adăposti înăuntru.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Vedere la persoana a 3-a pentru soldat (V, se reține; pe telefon — Comenzi) și o cameră lină pentru vehicule, cu un marcaj unde va lovi tunul.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Versiunea v7.6 rămâne în meniul „🕘 Versiunea jocului” în caz că o preferi.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Facțiunile Consorțiul / Roiul cu alegere înainte de meci, cratere de explozie, vedere la persoana a 3-a",
"and older: v7.6, v7.5, milestones v1–v7.0":"și mai vechi: v7.6, v7.5, repere v1–v7.0",
