"Anomaly ahead! The vein is singing — go around!":"Anomalie în față! Filonul cântă — ocolește!",
"Hear that hum? A singing vein. Keep clear!":"Auzi zumzetul ăla? Un filon cântător. Stai departe!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomalie! Aerul se rotește — e un vârtej, ocolește!",
"Rocks floating in the air… A whirlpool! Stay out!":"Pietre plutind în aer… Un vârtej! Nu intra!",
"Anomaly ahead — it is crackling with current!":"Anomalie în față — trosnește de curent!",
"Rods and lightning — a Crackler. It loves armour!":"Vergele și fulgere — un Pocnitor. Îi plac armurile!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomalie! Pământul tremură de căldură — un Jar!",
"Careful, a Brazier underfoot!":"Atenție, un Jar sub picioare!",
"Anomaly — green mist! Acid, hold your breath!":"Anomalie — ceață verde! Acid, nu respirați!",
"The mist is drifting our way, go around!":"Ceața se târăște spre noi, ocolim!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Anomalie! Aerul e ca sticla — o Lentilă, îndoaie gloanțele!",
"Everything is warping… a Lens nearby!":"Totul se deformează… o Lentilă prin apropiere!",
"Ha! An enemy walked right into the anomaly!":"Ha! Un inamic a intrat direct în anomalie!",
"Got him! Lure them into anomalies!":"L-am prins! Atrage-i în anomalii!",
"Beautiful zap! One less tin can.":"Ce descărcare frumoasă! Una mai puțin de fier vechi.",
"The anomaly got me!":"M-a prins anomalia!",
