"They say veins hide artifacts. Only first the vein sings…":"Se zice că în filoane se ascund artefacte. Doar că mai întâi filonul cântă…",
"Throw a bolt first, then walk. Old habit.":"Mai întâi aruncă un șurub, apoi mergi. Obicei vechi.",
