" — close":" — închide",
"Supply drop":"Container de aprovizionare",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Lasă un container lângă forțele tale: muniție, grenade, rachete, piese de armă, kit de reparații.",
"\"Grad\" rocket strike":"Lovitura „Grad”",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 rachete pe o suprafață mare după 3 secunde — mai rapid și mai larg decât bombardamentul de artilerie.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Sprijin: container, recunoaștere, „Grad”, bombardament de artilerie (apoi 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"ATENȚIE: „Grad” al Roiului asupra zonei tale!",
"Warning! Rocket salvo on our position!":"Atenție! Salvă de rachete asupra poziției noastre!",
"take the supply crate":"ia containerul de aprovizionare",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomalii pe meteorit (valul 1): „Filonul Cântător” — un cristal verde strălucitor care zumzăie și lovește cu pulsuri ritmice pe toți cei din apropiere; „Vârtejul” trage și aruncă, „Pocnitorul” descarcă arcuri electrice între vergele, „Jarul” izbucnește în flăcări sub picioare, „Ceața acidă” și „Lentila” (îndoaie gloanțele și imaginea) plutesc de colo-colo.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomaliile se simt dinainte (zumzet, strălucire, aer încins). Descarc-o cu o grenadă, o rachetă sau un șurub (E lângă ea): se liniștește și uneori lasă un artefact cu un plus și un minus. Echipa te avertizează la stație, iar inamicii (și aliații) mai nimeresc uneori în ele — atrage-i!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Sprijin pentru puncte de comandă: 4 în luptă (📡 pe telefon) — container de aprovizionare, scanare de recunoaștere, lovitura „Grad”, bombardament de artilerie la reticul. Strategul vede anomaliile pe hartă abia după o scanare.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Containere de aprovizionare în ruinele vechilor expediții, lângă cartierele generale și lângă clădirile terminate: muniție, grenade, rachete, piese de armă (deblochează accesorii).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"Versiunea v7.7 rămâne în meniul „🕘 Versiunea jocului”. Anomaliile pot fi dezactivate în Setări.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomalii („Filonul Cântător” și încă 5), descărcare cu șurub sau grenadă, artefacte, apeluri de sprijin pentru PC, containere de aprovizionare",
"and older: v7.7, v7.6, milestones v1–v7.0":"și mai vechi: v7.7, v7.6, repere v1–v7.0",
"New in v7.8":"Noutăți în v7.8",
"NEW IN v7.8":"NOUTĂȚI ÎN v7.8",
"Close":"Închide",
"Anomalies on the meteor":"Anomalii pe meteorit",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ din colț deschide meniul de pauză: Continuă, Reîncepe, Antrenament, Grafică, Setări, Meniu principal (cu confirmare). Telefon: ☰ sus în dreapta (acțiunile de luptă — dala „⚡ Acțiuni”); PC: butonul „☰ Meniu” sus în dreapta sau Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Grafica este implicit mereu cea normală — Dendy doar dacă o alegi tu: comutatorul „Grafică: Normală / Dendy (8-bit) / 16-bit” e chiar în meniul principal și în pauză. Dacă jocul se blochează rău, apare un sfat cu butonul „Activează Dendy”.",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon și tabletă: butonul de acțiune „✋” din dreapta apare doar când e ceva de făcut în apropiere — „Ia” (ascunzătoare, container), „Urcă” (vehicul, turelă, tun), „Construiește”, „Coboară”, „Șurub” la o anomalie. Poți și să atingi pur și simplu obiectul evidențiat.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strategie: ține degetul ~0,3 s (telefonul vibrează, apare un inel galben) și trage — un chenar de selecție; o glisare obișnuită mută camera. Există și butonul „Chenar” în dreapta; în antrenament, pasul „Chenar” acceptă și atingerea unei echipe.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: butoanele mici sunt mai ușor de apăsat, lista de sprijin 📡 e mai mare, panourile de strategie nu mai acoperă pauza și ecranul de rezultate. Versiunea v7.8 rămâne în meniul „🕘 Versiunea jocului”.",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Meniul ☰ pe telefon și PC, fără Dendy automat, butonul „✋” pe touch, selecție cu chenar pe telefon",
"16-bit":"16-bit",
"Lagging? Try the Dendy graphics — they are lighter.":"Se blochează? Încearcă grafica Dendy — e mai ușoară.",
