"Commander — still in development":"Comandant — încă în dezvoltare",
"Pause: resume, restart, training, graphics, settings, main menu":"Pauză: continuă, reîncepe, antrenament, grafică, setări, meniu principal",
"Menu: pause, restart, training, graphics, settings":"Meniu: pauză, reîncepe, antrenament, grafică, setări",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Ține degetul pe sol ~0,3 s — telefonul vibrează și apare un inel galben — apoi, fără să ridici degetul, trage: apare un chenar. Sau folosește butonul „Chenar” din dreapta. Poți și să atingi pur și simplu o echipă.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Pentru ecran complet pe iPhone: „Partajează” ⬆ → „Adaugă pe ecranul principal” — jocul se deschide fără barele Safari.",
"Open portal-meteor.pages.dev for that.":"Pentru asta, deschide site-ul portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Atingere — selectează · atingere pe sol — mergi · ține apăsat — meniul de ordine · ține apăsat și trage — chenar · 2 degete — zoom",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Eroină asasin: salturi-teleport, katana, shurikeni. Sare singură prin zonele inamicului și taie roboții în bucăți. 1 pe tabără.",
"Shadow protocol":"Protocol „Umbră”",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Cercetare: deblochează robo-ninja în Cazarmă. Necesită o fabrică de mecha terminată.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Erou (1 pe tabără): se teleportează singură prin zonele inamicului și taie roboții în bucăți; preia controlul ca să joci manual.",
"is ready. She works on her own (AUTO) — possess her to play manually":"este gata. Lucrează singură (AUTO) — preia controlul ca să joci manual",
"Robo-ninja ready for action":"Robo-ninja este gata de luptă",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Recunoaștere: inamicul are o robo-ninja!",
"Warning! The enemy has a robo-ninja. Stay together":"Atenție! Inamicul are o robo-ninja. Rămâneți împreună",
