"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ DUEL DE NINJA! Blochează chiar înainte de lovitură pentru a para, sari ca să eviți. Urmărește sclipirea de armare",
"The two ninjas have met in a duel!":"Cele două ninja s-au întâlnit într-un duel!",
"⚔ Duel won! Our ninja prevails":"⚔ Duel câștigat! Ninja noastră a învins",
