"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: sare singură prin zonele inamicului și taie. Joystick / WASD — pauză 1.5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Manual: atingere pe inamic — salt și lovitură, glisare — tăietură, 🛡 — blocare",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Control manual: clic stânga — katana, clic dreapta — blocare, Shift — salt, Q — shurikeni, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: atingere pe inamic — salt și lovitură, glisare în dreapta — tăiere, ● — lovitură, 🛡 — blocare (la timp = parare), ⇑ — salt scurt, ✦ — shurikeni, ◎ — teleportare, AUTO — singură",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: clic stânga — katana (ține apăsat — lovitură grea), clic dreapta — blocare (la timp = parare), Shift/Z — salt scurt, Q — shurikeni, G — teleportare la țintă, săritură în aer — dublu salt / alergare pe perete, {0} — AUTO",
