"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Radio Portal Meteor: peste 100 de piese de EDMITRY chiar în joc — butonul 📻 (PC: tasta 5, [ ] — piesă). Muzica se încarcă la cerere și nu îngreunează jocul; volum și pornire automată în Setări, plus link „Ascultă pe Spotify”.",
