"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 în dreapta — Radio Portal Meteor: muzică de EDMITRY în timpul luptei.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Radio Portal Meteor: muzică de EDMITRY în timpul luptei. [ ] — piesă.",
"Radio Portal Meteor (EDMITRY): volume":"Radio Portal Meteor (EDMITRY): volum",
"Radio: start by itself in battle":"Radio: pornește singur în luptă",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: o cyborg cu katană. Se deblochează în Cazarmă prin cercetarea „Protocol Umbră” (necesită o fabrică de mecha). Se teleportează singură în zonele inamice, taie inamicii în bucăți (fără sânge — scântei), salturi scurte, shurikeni, dueluri cu ninja inamică. Preia controlul — mod AUTO sau control manual (pe telefon — butoane proprii).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Radio Portal Meteor: 103 piese EDMITRY chiar în joc. Tasta 5 (se poate remapa), pe telefon — ☰ → Setări → Sunet. Volumul și „pornește singur în luptă” sunt în setări; muzica se reduce la explozii și sub vocea stației radio.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Limbi noi: uzbecă și tadjică — complete; chineză, spaniolă, portugheză — parțiale. Selector nou de limbă în meniu, lângă „Meci nou”.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: „ascunde pictogramele” 👁 adună butoanele rămase într-o coloană ordonată la marginea din dreapta; portretul nu se mai suprapune; iPhone — jocul nu mai intră în conflict cu gesturile Safari, iar „Partajează → Adaugă pe ecranul principal” îl pornește pe tot ecranul.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Din v7.8.1: meniul ☰ din colț (pauză, reia, antrenament, grafică), fără Dendy automat, butonul de acțiune ✋ pe telefon. v7.8.1 și v7.8 rămân în meniul „🕘 Versiunea jocului”.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Robo-ninja, radio EDMITRY, uzbecă și tadjică, confort pe telefon și iPhone",
