"Napalm":"Napalm",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"O zonă de foc de 12 m arde 9 secunde: daune în timp, suprimare, fum. După 2.5 s. Aprinde metanul.",
