"here, a gun from the trunk — MG for 90 s":"na, o armă din portbagaj — mitralieră 90 s",
"a pod is launched from the base — a trooper for your squad":"din bază vine o capsulă — un soldat pentru echipa ta",
"a satellite will cover you for 20 s":"un satelit te va acoperi 20 s",
"+2 CP for HQ":"+2 PC pentru CG",
"Pod from the base: {0} joins the squad":"Capsulă din bază: {0} în echipă",
"Living world: your units ask for help, heroes give quests. Card on the right — ✕ to dismiss.":"Lume vie: ai tăi cer ajutor, eroii dau misiuni. Cardul din dreapta — ✕ ca să-l închizi.",
"Living world: your units ask for help, heroes give quests. Y — accept, N — decline.":"Lume vie: ai tăi cer ajutor, eroii dau misiuni. Y — acceptă, N — refuză.",
