"HELP":"AJUTOR",
"GENERATOR":"GENERATOR",
"RELAY":"RELEU",
"SABOTAGE":"SABOTAJ",
"Living world: requests, hero quests, breakthrough ops":"Lume vie: cereri ale alor tăi, misiuni de erou, operațiuni decisive",
"Living world":"Lume vie",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Ai tăi cer ajutor și te răsplătesc, eroii dau misiuni, un front blocat se sparge printr-o operațiune",
"A request":"O cerere",
"Breakthrough":"Punct de cumpănă",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Ai tăi cer uneori ajutor: apel radio, cardul „CERERE\" și marcajul ✋. O echipă e blocată — distruge inamicii din apropierea ei. Recompensă: un soldat cu capsulă din bază, o armă din portbagajul unui buggy, locul trăgătorului sau acoperire orbitală. Nu acum — ✕ sau ignoră.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteranul iscoadă „Bufnița\" îți propune o misiune. Y — acceptă (N — refuză). Mergi la marcajul ★, elimină paza și stai lângă pilot 3 s — se alătură echipei tale.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Frontul s-a blocat — CG propune o operațiune decisivă. Y — acceptă. Ține releul 8 s fără inamici în apropiere: harta inamicului e vizibilă 60 s. Generatorul — turelele inamice tac 2 min. În modul Strateg — „Atribuie echipei\". Și inamicul poate face asta: urmărește ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Ai tăi cer ajutor: cardul „CERERE\" și marcajul ✋. Distruge inamicii de lângă echipa blocată — primești o recompensă. ✕ — omite.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Eroul „Bufnița\" propune o misiune — atinge „Acceptă\". Mergi la ★, elimină paza, stai lângă pilot.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Frontul s-a blocat — atinge „Acceptă\" și ține releul 8 s: harta inamicului se deschide pentru un minut.",
"Pod redeploy from the base: {0} m — through the sky portal":"Redesfășurare cu capsula din bază: {0} m — prin portalul ceresc",
"Pod away from the base! Hold on — exit over the target.":"Capsula a plecat din bază! Țineți-vă — ieșirea e deasupra țintei.",
"Landed at the objective!":"Desant la țintă!",
"LAUNCH FROM BASE":"LANSARE DIN BAZĂ",
"LANDING":"ATERIZARE",
"REDEPLOY":"REDISTRIBUIRE",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Pâsla de oțel s-a lipit de tine — corodează armura −2/s. Stai 3 s pe loc în afara luptei sau găsește un inginer",
"An engineer brushed the fluff off":"Un inginer a curățat puful",
"The fluff fell off — armour is safe":"Puful a căzut — armura e intactă",
"The firefly swarm scattered by the blast":"Roiul de licurici a fost împrăștiat de explozie",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"PUF DE OȚEL −2/s · stai 3 s în afara luptei sau mergi la un inginer",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Convoiul lui Stângaci e gata: doi „Șacali\". Rămâi aproape — te așteaptă",
"The convoy is waiting for you":"Convoiul te așteaptă",
"Ambush! Cover the Jackals!":"Ambuscadă! Acoperă \"Șacalii\"!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"convoiul a ajuns ({0} din 2)! +2 PC, +150 minereu, \"Șacalii\" sunt ai tăi",
"The parts are delivered! Thanks, commander.":"Piesele au ajuns! Mulțumesc, comandante.",
"Show tips again":"Arată din nou indiciile",
"Reset":"Resetează",
"Sure? Tap again":"Sigur? Atinge încă o dată",
"Done":"Gata",
"Tips and lessons will show again":"Indiciile și lecțiile vor apărea din nou",
"Steel fluff":"Puf de oțel",
"Rootwalker":"Umblă-Rădăcină",
"Firefly swarm":"Roi de licurici",
"Steel dandelions — Steel fluff! It sticks and eats armour!":"Păpădii de oțel — Puf de oțel! Se lipește și mănâncă armura!",
"Fluff in the air — keep out of the meadow and away from the infected!":"Pufu-i în aer — nu intra în poiană și nu te atinge de cei infectați!",
"fluff blown away, dormant for 25 s · +0.5 CP":"pufu-a fost suflat, poiana doarme 25 s · +0.5 PC",
"My crew is hauling parts to point {0}. Escort the column — there may be an ambush.":"Băieții mei duc piese la punctul {0}. Escortează coloana — pe drum ne-ar putea aștepta cineva.",
"Escort the convoy to point {0}":"Escortează convoiul la punctul {0}",
